import assert from 'node:assert/strict'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import {spawn,spawnSync} from 'node:child_process'
import {build} from 'esbuild'

const order=fs.readFileSync('src/features/sections/CreateOrderSection.tsx','utf8')
assert(order.indexOf('Клиент и условия заказа')<order.indexOf('Товары в заказе'),'Customer details must come first')
assert(order.includes('<MainWorkshopOrderModal'),'Workshop form must open separately')
assert(!order.includes('setManualMode('),'Old manual draft-in-basket path must be absent')
assert(order.includes('setTimeout(()=>setNotice(null),2200'),'Confirmation must disappear automatically')
assert(order.includes('main-basket-details'),'Basket must separate name from identifiable variant details')
const picker=fs.readFileSync('src/features/orders/MainClothingSourcePicker.tsx','utf8')
assert(!picker.includes('colorTones'),'Decorative color labels must not make false claims about colors')
assert(!picker.includes('clothing-source-tone'),'Swatches not verified against product colors must be absent')
assert(picker.includes('clothing-source-refinements'),'Large material families require local filters')

const chrome=process.env.CHROME_BIN||'/usr/bin/google-chrome'
assert(fs.existsSync(chrome),'Real Chrome is required')
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'orders-workshop-ux-'))
const stock={physical:5,reserved:0,cachedReserved:0,free:5,listed:true}
const rows=[]
for(let i=0;i<20;i++){
 rows.push({
  variantId:1000+i,productId:1,productName:'БАЯН СҰЛУ ШАПАН',category:'adult',
  gender:i%2===0?'ЖЕН':'МУЖ',color:i%3===0?'БЕЖЕВЫЙ':i%3===1?'БЕЛЫЙ':'ЧЕРНЫЙ',
  material:'ЗАМША ВЕЛЮР',length:i%2===0?'СТАНДАРТ':'ДЛИННЫЙ',
  size:String(42+(i%7)*2),salePrice:45000,warehouse:stock,boutique:stock
 })
}
const app=[
 "import React,{useState} from 'react'",
 "import {createRoot} from 'react-dom/client'",
 "import {flushSync} from 'react-dom'",
 "import {MainClothingSourcePicker} from './src/features/orders/MainClothingSourcePicker.tsx'",
 "import {MainWorkshopOrderModal} from './src/features/orders/MainWorkshopOrderModal.tsx'",
 'const rows='+JSON.stringify(rows)+';',
 'window.__saved=[];window.__modalOpen=0;',
 "function View(){const [modal,setModal]=useState(false);window.__modalOpen=Number(modal);return <div>",
 "<MainClothingSourcePicker initialVariants={rows} allocated={new Map()} onCommit={()=>{}} onManual={(origin,preset)=>setModal({origin,preset})}/>",
 "<span data-order-items={window.__saved.length}></span>",
 "{modal&&<MainWorkshopOrderModal source={modal.origin} preset={modal.preset} onClose={()=>setModal(false)} onSave={item=>{window.__saved.push(item);setModal(false)}} suggestions={{products:['БАЯН СҰЛУ ШАПАН'],colors:['БЕЖЕВЫЙ']}}/>}",
 "</div>}",
 "flushSync(()=>createRoot(document.getElementById('root')).render(<View/>))"
].join('\n')
const result=await build({stdin:{contents:app,loader:'jsx',resolveDir:process.cwd(),sourcefile:'workshop-ui-test.jsx'},
 bundle:true,write:false,outdir:dir,format:'iife',platform:'browser',target:'chrome120',
 jsx:'automatic',jsxImportSource:'react',logLevel:'error'})
fs.writeFileSync(path.join(dir,'bundle.js'),result.outputFiles.find(x=>x.path.endsWith('.js')).text)
const css=fs.readFileSync('src/styles/main-clothing-source-picker.css','utf8')+
 fs.readFileSync('src/styles/main-sale-picker.css','utf8')

const browser=["const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));","const click=async el=>{if(!el)throw Error('Missing control');el.click();await wait(100)};","const change=(node,value)=>{if(!node)throw Error('Missing input');const proto=node.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype;const set=Object.getOwnPropertyDescriptor(proto,'value').set;set.call(node,value);node.dispatchEvent(new Event('input',{bubbles:true}))};","(async()=>{try{","await wait(300);","if(document.querySelector('.clothing-source-tone'))throw Error('Unverified decorative color still visible');","await click(document.querySelector('.clothing-source-model'));","const filters=document.querySelector('.clothing-source-refinements');if(!filters)throw Error('Missing large-execution filters');","const color=filters.querySelector('select[aria-label=\"Фильтр по цвету\"]');if(!color)throw Error('Missing color filter');","color.value='БЕЖЕВЫЙ';color.dispatchEvent(new Event('change',{bubbles:true}));await wait(100);","const names=[...document.querySelectorAll('.clothing-source-color-title strong')].map(el=>el.textContent);","if(names.length!==1||names[0]!=='БЕЖЕВЫЙ')throw Error('Color filter did not narrow selection');","const size=filters.querySelector('select[aria-label=\"Фильтр по размеру\"]');size.value='42';size.dispatchEvent(new Event('change',{bubbles:true}));await wait(90);","if(!document.querySelector('.clothing-source-refinement-head')?.textContent.includes('из 20'))throw Error('Filtered count unavailable');","await click(document.querySelector('.clothing-source-workshop-tab'));","let modal=document.querySelector('[role=dialog][aria-modal=true]');if(!modal)throw Error('Workshop modal missing');","if(window.__saved.length)throw Error('Unsaved workshop item already committed');","for(const title of ['Какой товар изготовить','Количество и цена','Задание и комментарий','Срок изготовления'])if(!modal.textContent.includes(title))throw Error('Missing section: '+title);","await click(modal.querySelector('.main-workshop-close'));","if(document.querySelector('[role=dialog]')||window.__saved.length)throw Error('Modal cancel committed item');","await click(document.querySelector('.clothing-source-workshop-tab'));modal=document.querySelector('[role=dialog]');","","const byLabel=word=>[...modal.querySelectorAll('.main-workshop-field')].find(el=>el.textContent.includes(word))?.querySelector('input,textarea');","change(byLabel('Название товара'),'БАЯН СҰЛУ ШАПАН');change(byLabel('Размер *'),'46');","modal.querySelector('button[type=submit]').click();await wait(80);","if(!modal.querySelector('[role=alert]')||window.__saved.length)throw Error('Incomplete Workshop garment accepted');","const chooseSelect=(el,value)=>{el.value=value;el.dispatchEvent(new Event('change',{bubbles:true}))};","chooseSelect(modal.querySelector('select'),'ВЗРОСЛЫЙ');","chooseSelect([...modal.querySelectorAll('select')].find(el=>[...el.options].some(option=>option.value==='ЖЕН')),'ЖЕН');","change(byLabel('Цвет'),'БЕЖЕВЫЙ');change(byLabel('Материал'),'ЗАМША ВЕЛЮР');","change(byLabel('Длина'),'СТАНДАРТ');","change(byLabel('Цена за штуку'),'32000');change(byLabel('Что нужно изготовить'),'Пожелание к пошиву');","await click(modal.querySelector('.main-workshop-checkbox input'));","change(byLabel('Нужно до'),'2026-11-30');","modal.querySelector('button[type=submit]').click();await wait(170);","if(window.__saved.length!==1||window.__saved[0].productName!=='БАЯН СҰЛУ ШАПАН'||window.__saved[0].workshopComment!=='Пожелание к пошиву'||!window.__saved[0].workshopUrgent||window.__saved[0].workshopDueDate!=='2026-11-30')throw Error('Workshop data not committed correctly');","if(document.querySelector('[role=dialog]'))throw Error('Modal not closed after save');","if(window.__saved[0].sourceType!=='workshop')throw Error('Workshop source missing');","if(!window.__saved[0].manualCatalogEntry)throw Error('Manual Workshop flag not persisted')","if(document.querySelector('datalist'))throw Error('Native uncontrolled datalist still in use');","await click(document.querySelector('.clothing-source-own-variant button'));","modal=document.querySelector('[role=dialog]');if(!modal)throw Error('Model-local custom variant form missing');","if(modal.querySelector('input[placeholder=\"Например, Баян Сұлу шапан\"]')?.value!=='БАЯН СҰЛУ ШАПАН')throw Error('Model name was not prefilled');","if(![...modal.querySelectorAll('.main-manual-lookup input')].some(el=>el.value==='ЗАМША ВЕЛЮР'))throw Error('Selected material not prefilled');","await click(modal.querySelector('.main-manual-arrow'));","if(!modal.querySelector('.main-manual-options button'))throw Error('Click-open in-app suggestions did not show existing reference choices');","await click(modal.querySelector('.main-manual-arrow'));","modal=document.querySelector('[role=dialog]');if(!modal||!modal.textContent.includes('Товар со Склада'))throw Error('Manual warehouse form not opened');","if(!modal.querySelector('.main-workshop-source-notice'))throw Error('Missing warehouse-specific warning');","change(byLabel('Размер *'),'50');","change(byLabel('Цвет'),'ЗЕЛЁНЫЙ');change(byLabel('Материал'),'НОВАЯ ТКАНЬ');change(byLabel('Длина'),'СТАНДАРТ');","chooseSelect(modal.querySelector('select'),'ВЗРОСЛЫЙ');","const genderSelect=[...modal.querySelectorAll('select')].find(x=>[...x.options].some(o=>o.value==='ЖЕН'));chooseSelect(genderSelect,'ЖЕН');","change(byLabel('Цена за штуку'),'57000');","await click(modal.querySelector('button[type=submit]'));","if(window.__saved.length!==2||window.__saved[1].sourceType!=='warehouse'||!window.__saved[1].manualCatalogEntry||!window.__saved[1].shortageAcknowledged||window.__saved[1].catalogVariantId)throw Error('Manual warehouse item was turned into Workshop or guessed SKU');","if(window.__saved[1].productName!=='БАЯН СҰЛУ ШАПАН')throw Error('Source-local missing variant did not keep model identity');","await click([...document.querySelectorAll('.clothing-source-tabs>button')].find(el=>el.textContent==='Бутик'));","if(!document.querySelector('.clothing-source-own-variant'))await click(document.querySelector('.clothing-source-model'));","await click(document.querySelector('.clothing-source-own-variant button'));","modal=document.querySelector('[role=dialog]');if(!modal||!modal.textContent.includes('Товар из Бутика'))throw Error('Manual boutique form missing');","await click(modal.querySelector('.main-workshop-close'));","if(window.__saved.length!==2)throw Error('Cancel from Boutique form added item');","await click([...document.querySelectorAll('.clothing-source-tabs>button')].find(el=>el.textContent==='Склад'));","if(!document.querySelector('.clothing-source-quick-link'))await click(document.querySelector('.clothing-source-model'));","if(!document.querySelector('.clothing-source-quick-link'))throw Error('Quick missing-size control not visible');","await click(document.querySelector('.clothing-source-quick-link'));","modal=document.querySelector('[role=dialog]');if(!modal||!modal.querySelector('.main-workshop-quick'))throw Error('Guided size form missing');","if(modal.querySelectorAll('.main-workshop-quick .main-manual-lookup input').length!==1)throw Error('Guided form should ask only one characteristic');","if(modal.querySelector('.main-workshop-quick-base strong')?.textContent!=='БАЯН СҰЛУ ШАПАН')throw Error('Selected model not inherited');","if(!modal.textContent.includes('Товар будет оформлен из Склада'))throw Error('Warehouse source not explained');","await click(modal.querySelector('button[type=submit]'));if(!modal.querySelector('[role=alert]')||window.__saved.length!==2)throw Error('Blank guided size was accepted');","change(modal.querySelector('.main-workshop-quick input'),'58');await click(modal.querySelector('button[type=submit]'));","if(window.__saved.length!==3||window.__saved[2].size!=='58'||window.__saved[2].sourceType!=='warehouse'||window.__saved[2].catalogVariantId||!window.__saved[2].manualCatalogEntry||window.__saved[2].material!=='ЗАМША ВЕЛЮР'||window.__saved[2].unitPrice!==45000)throw Error('Guided size did not safely preserve base identity');","if(document.querySelector('[role=dialog]'))throw Error('Guided size did not close');","await click(document.querySelector('.clothing-source-color .clothing-source-size'));","if(!document.querySelector('.clothing-source-quick-actions'))throw Error('Quick other-color button missing after choosing exact item');","const originalColor=document.querySelector('.clothing-source-color .clothing-source-color-title strong').textContent;","await click([...document.querySelectorAll('.clothing-source-quick-actions button')].find(el=>el.textContent==='Другой цвет'));","modal=document.querySelector('[role=dialog]');if(!modal?.querySelector('.main-workshop-quick'))throw Error('Guided color modal missing');","change(modal.querySelector('.main-workshop-quick input'),originalColor);await click(modal.querySelector('button[type=submit]'));","if(!modal.querySelector('[role=alert]')||window.__saved.length!==3)throw Error('Unchanged color accepted');","change(modal.querySelector('.main-workshop-quick input'),'ЗЕЛЁНЫЙ');await click(modal.querySelector('button[type=submit]'));","if(window.__saved.length!==4||window.__saved[3].color!=='ЗЕЛЁНЫЙ'||window.__saved[3].sourceType!=='warehouse'||window.__saved[3].catalogVariantId||!window.__saved[3].size||!window.__saved[3].manualCatalogEntry)throw Error('Guided color failed to preserve size and source');","if(document.querySelector('[role=dialog]'))throw Error('Guided color modal did not close');","if(!document.querySelector('.clothing-source-quick-link'))throw Error('Size shortcut lost after guided color');","await click(document.querySelector('.clothing-source-quick-link'));","modal=document.querySelector('[role=dialog]');await click(modal.querySelector('.main-workshop-close'));","if(window.__saved.length!==4)throw Error('Cancelled quick entry was saved');","document.body.dataset.reviewPass='yes';","}catch(e){document.body.dataset.reviewPass='no';document.body.dataset.reviewError=String(e.message)}","})();"].join('\n')
fs.writeFileSync(path.join(dir,'index.html'),'<html lang="ru"><meta charset="utf-8"><style>body{font:14px Arial;background:#eff4fa;padding:12px}.clothing-source-picker{max-width:750px;background:white;padding:22px}'+css+'</style><div id="root"></div><script src="/bundle.js"></script><script>'+browser+'</script></html>')
const http=spawn('python3',['-m','http.server','38929','--bind','127.0.0.1','--directory',dir],{stdio:'ignore'})
await new Promise(resolve=>setTimeout(resolve,650))
let run
try{run=spawnSync(chrome,['--headless=new','--no-sandbox','--disable-gpu','--disable-dev-shm-usage','--virtual-time-budget=7500','--dump-dom','http://127.0.0.1:38929/index.html'],{encoding:'utf8',timeout:45000,maxBuffer:18*1024*1024})}finally{http.kill()}
assert.equal(run.status,0,'Chrome failed: '+String(run.stderr).slice(-1000))
const failure=run.stdout.match(/data-review-error="([^"]*)"/)?.[1]||'unknown'
assert.match(run.stdout,/data-review-pass="yes"/,'Review browser acceptance failed: '+failure)
console.log('BRANCH2_ORDER_UX_PASS: customer-first, clear basket, material filters, workshop modal cancel/save and deadline')
